import {SCENARIOS} from './model.js';
import {generateScenario} from './practice.js';
import {projectSurface} from './surfaces.js';
import {vegetation} from './landscape.js';
import {greenYardages} from './guidance.js';
// A fixed, read-only art study. No settings, score, random-bank or storage writes.
const scene=generateScenario(SCENARIOS.find(s=>s.id==='tucked'),17),project=p=>projectSurface(scene,p,scene.elevationM),point=p=>{const a=project(p);return `${a.x.toFixed(2)},${a.y.toFixed(2)}`;},poly=points=>points.map(([x,y])=>point({x,y})).join(' ');
const ellipse=(g,extra=0)=>Array.from({length:96},(_,i)=>{const a=i/96*Math.PI*2;return[g.x+Math.cos(a)*(g.rx+extra),g.y+Math.sin(a)*(g.ry+extra)];});
// Smooth organic outlines with deterministic variation; no new tree positions.
function closedCurve(points){const n=v=>v.toFixed(2);return points.map((p,i)=>{const a=points[(i+points.length-1)%points.length],b=points[(i+1)%points.length],c=points[(i+2)%points.length];return `${i?'':'M'+n(p[0])+','+n(p[1])}C${n(p[0]+(b[0]-a[0])/6)},${n(p[1]+(b[1]-a[1])/6)} ${n(b[0]-(c[0]-p[0])/6)},${n(b[1]-(c[1]-p[1])/6)} ${n(b[0])},${n(b[1])}`;}).join(' ')+'Z';}
function tree(p,index){
 const base=project(p),top=project({...p,z:p.height}),h=Math.max(3,base.y-top.y),w=Math.max(1,p.width*1000/(p.y+6)),phase=p.x*1.7+p.y*.13,tone=p.tone,wide=.83+.1*Math.sin(phase);
 const crown=closedCurve(Array.from({length:40},(_,i)=>{const a=i/40*Math.PI*2,r=.87+.065*Math.sin(a*7+phase)+.045*Math.cos(a*11-phase);return [w*Math.cos(a)*r*wide,-h*.64+h*.35*Math.sin(a)*r];}));
 const id='p-crown-'+index;
 let out=`<g class="study-tree" transform="translate(${base.x.toFixed(2)},${base.y.toFixed(2)})" opacity="${p.y>180?.82:1}"><defs><clipPath id="${id}"><path d="${crown}"/></clipPath></defs><ellipse cx="${w*.6}" cy="3" rx="${w*1.4}" ry="${w*.16}" fill="#213d2920"/><path d="M${-w*.06} 0L${w*.04} ${-h*.72}M0 ${-h*.28}L${-w*.4} ${-h*.62}M0 ${-h*.4}L${w*.36} ${-h*.75}" stroke="#655c43" stroke-width="${Math.max(1,w*.15)}" stroke-linecap="round" fill="none"/><path d="M${-w*.03} 0L${w*.05} ${-h*.61}" stroke="#b3a477" stroke-width="${Math.max(.6,w*.035)}" opacity=".5"/><path d="${crown}" fill="url(#p-canopy${tone})"/><g clip-path="url(#${id})">`;
 for(let j=0;j<5;j++){
  const cx=Math.sin(phase+j*2.4)*w*.52,cy=-h*(.44+.09*j),rx=w*(.22+.07*Math.sin(phase+j)**2),ry=h*(.075+.018*Math.cos(j+phase));
  const patch=closedCurve(Array.from({length:16},(_,k)=>{const a=k/16*Math.PI*2,r=.8+.17*Math.sin(a*5+j+phase);return[cx+Math.cos(a)*rx*r,cy+Math.sin(a)*ry*r];}));
  out+=`<path d="${patch}" fill="${j%2?'#b4c17b':'#244c38'}" opacity="${j%2?.07:.08}"/>`;
 }
 return out+`<path d="M${w*.2} ${-h}Q${w*.8} ${-h*.6} ${w*.35} ${-h*.25}H${w*1.3}V${-h}Z" fill="#1e4934" opacity=".13"/></g></g>`;
}
function hazardArt(h,i){
 const points=poly(h.poly),screen=h.poly.map(([x,y])=>project({x,y})),minX=Math.min(...screen.map(p=>p.x)),maxX=Math.max(...screen.map(p=>p.x)),minY=Math.min(...screen.map(p=>p.y)),maxY=Math.max(...screen.map(p=>p.y)),cx=(minX+maxX)/2,cy=(minY+maxY)/2;
 let out=`<g data-study-hazard="${h.kind}"><defs><clipPath id="p-hazard${i}"><polygon points="${points}"/></clipPath></defs><polygon data-hazard-boundary="${h.kind}" points="${points}" fill="url(#p-${h.kind==='water'?'water':'sand'})"/><g clip-path="url(#p-hazard${i})">`;
 if(h.kind==='bunker'){
  // A shaded upper face and inset sand basin, clipped to the exact hazard edge.
  const basin=closedCurve(screen.map((p,j)=>[cx+(p.x-cx)*.79,cy+(p.y-cy)*.64+1.4+Math.sin(j)*.3]));
  out+=`<polygon points="${points}" fill="#a48b58"/><path d="${basin}" fill="url(#p-sand)"/><path d="${basin}" fill="none" stroke="#f8edcb" stroke-width="2" opacity=".65"/><polygon points="${points}" fill="none" stroke="#4c6436" stroke-width="6" opacity=".55"/><path d="M${minX-10} ${minY+.8}Q${cx} ${minY+4.5} ${maxX+10} ${minY+1}" fill="none" stroke="#3c4e2b" stroke-width="4" opacity=".4"/><polygon points="${points}" fill="url(#p-grain)"/>`;
  for(let y=minY+5;y<maxY;y+=3.5)out+=`<path d="M${cx-14} ${y}q12 .8 27 0" fill="none" stroke="#b7a579" stroke-width=".5" opacity=".23"/>`;
 }else{
  // Shadows, reflections and a shallow shelf stay inside the playable footprint.
  out+=`<polygon points="${points}" fill="none" stroke="#243f32" stroke-width="7" opacity=".35"/><polygon points="${points}" fill="none" stroke="#a0b8a1" stroke-width="3.5" opacity=".6"/>`;
  for(let j=0;j<6;j++){const x=minX+(maxX-minX)*(j/6),y=minY+(j%3)*1.2,depth=Math.max(5,(maxY-minY)*(.35+.05*j));out+=`<path d="M${x} ${y}q8 2 11 0l-2 ${depth*.4}q5 2 0 ${depth*.6}l-9-${depth*.25}q5-${depth*.4} 0-${depth*.75}Z" fill="#315b50" opacity=".11"/>`;}
  for(let y=minY+3;y<maxY;y+=5.3){for(let j=0;j<3;j++){const shift=(Math.sin(y*2.7+j*3)+1)*.08*(maxX-minX),x=minX+(maxX-minX)*j*.3+shift,length=(maxX-minX)*(.06+.065*(Math.cos(y+j)**2));out+=`<path d="M${x} ${y}q${length*.5} -.6 ${length} 0" fill="none" stroke="#d7ece0" stroke-width=".65" opacity=".28"/>`;}}

 }
 out+=`</g><polygon points="${points}" fill="none" stroke="${h.kind==='water'?'#657f5d':'#7c7048'}" stroke-width="1"/>`;
 if(h.kind==='water'){
  // Low bank grasses break up the straight visual edge without moving it.
  for(let j=0;j<screen.length;j++){const a=screen[j],b=screen[(j+1)%screen.length];for(let k=0;k<Math.hypot(a.x-b.x,a.y-b.y)/14;k++){const t=(k+.5)/Math.max(1,Math.hypot(a.x-b.x,a.y-b.y)/14),x=a.x+(b.x-a.x)*t,y=a.y+(b.y-a.y)*t;out+=`<path d="M${x} ${y}l-1.1-2.4m1.1 2.4l1.6-1.8" stroke="#879b65" stroke-width=".8" fill="none"/>`;}}
 }
 return out+'</g>';
}
function proposed(){let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 80 960 500" role="img" aria-label="Proposed illustrated woodland approach, same tucked hole and camera as the current view"><defs><linearGradient id="p-sky" gradientUnits="userSpaceOnUse" x1="0" y1="0" x2="0" y2="235"><stop stop-color="#73a9c0"/><stop offset=".7" stop-color="#d6e6dd"/><stop offset="1" stop-color="#edf0cf"/></linearGradient><linearGradient id="p-rough" x2="0" y2="1"><stop stop-color="#789559"/><stop offset="1" stop-color="#58774a"/></linearGradient><linearGradient id="p-fairway" x2=".25" y2="1"><stop stop-color="#91b967"/><stop offset=".5" stop-color="#79a756"/><stop offset="1" stop-color="#537f40"/></linearGradient><radialGradient id="p-green" cx=".35" cy=".25" r=".85"><stop stop-color="#b9d77e"/><stop offset="1" stop-color="#87ae57"/></radialGradient><linearGradient id="p-water" x1="0" y1="0" x2=".15" y2="1"><stop stop-color="#81b6b8"/><stop offset=".45" stop-color="#438d98"/><stop offset="1" stop-color="#286e7b"/></linearGradient><linearGradient id="p-sand" x2=".3" y2="1"><stop stop-color="#c9b17a"/><stop offset=".45" stop-color="#eee1b9"/><stop offset="1" stop-color="#faedc8"/></linearGradient><pattern id="p-ripples" width="95" height="12" patternUnits="userSpaceOnUse"><path d="M4 3h27M55 9h24M82 3h8" stroke="#e2f4df" stroke-width=".8" opacity=".25"/></pattern><pattern id="p-grass" width="39" height="28" patternUnits="userSpaceOnUse"><path d="M4 24l1-3M21 9l1-2M34 20l1-2" stroke="#d8e5aa" stroke-width=".7" opacity=".05"/></pattern><pattern id="p-grain" width="19" height="13" patternUnits="userSpaceOnUse"><circle cx="3" cy="8" r=".6" fill="#bba77c" opacity=".23"/><circle cx="13" cy="3" r=".5" fill="#fff7db" opacity=".4"/></pattern><filter id="p-haze" x="-50%" y="-100%" width="200%" height="300%"><feGaussianBlur stdDeviation="30"/></filter><clipPath id="p-fairway-clip"><polygon points="${poly(scene.fairway)}"/></clipPath><clipPath id="p-green-clip"><polygon points="${poly(ellipse(scene.green))}"/></clipPath>${[0,1,2].map((n)=>`<linearGradient id="p-canopy${n}" x2=".45" y2="1"><stop stop-color="${['#789653','#819c5c','#8aa366'][n]}"/><stop offset=".45" stop-color="${['#4d7544','#567e4b','#60874f'][n]}"/><stop offset="1" stop-color="#2b513b"/></linearGradient>`).join('')}</defs><rect width="960" height="580" fill="url(#p-sky)"/><ellipse cx="740" cy="148" rx="220" ry="112" fill="#fdf4ce" opacity=".16" filter="url(#p-haze)"/><path d="M0 237Q140 206 280 232T540 221T960 228V310H0Z" fill="#8ca58b" opacity=".4"/><path d="M0 240Q175 223 280 242T590 232T960 242V300H0Z" fill="#718e73" opacity=".32"/><path d="M120 130q26-18 55-4q12-15 36-2q27-7 42 9q-54 7-133-3M650 86q29-19 55-5q31-12 67 10q-51 6-122-5" fill="#f6f7e2" opacity=".35"/><rect y="235" width="960" height="345" fill="url(#p-rough)"/><polygon points="${poly(scene.fairway)}" fill="url(#p-fairway)" stroke="#a8be78" stroke-width="2.5"/><g clip-path="url(#p-fairway-clip)">`;
 for(let y=0;y<scene.maxY;y+=16)svg+=`<polygon points="${poly([[-180,y],[180,y],[180,y+8],[-180,y+8]])}" fill="#c4d887" opacity=".075"/>`;
 svg+='</g><rect y="235" width="960" height="345" fill="url(#p-grass)"/>';
 svg+=`<polygon points="${poly(ellipse(scene.green,2.1))}" fill="#689144"/><polygon points="${poly(ellipse(scene.green))}" fill="url(#p-green)" stroke="#72984c" stroke-width="1"/><g clip-path="url(#p-green-clip)">`;
 for(let y=scene.green.y-scene.green.ry;y<scene.green.y+scene.green.ry;y+=5)svg+=`<polygon points="${poly([[-180,y],[180,y],[180,y+2.5],[-180,y+2.5]])}" fill="#def0a4" opacity=".11"/>`;
 svg+='</g>';
 svg+=scene.hazards.filter(h=>['water','bunker'].includes(h.kind)).map(hazardArt).join('');
 // All trees retain their existing world position, height and corridor spacing.
 svg+=vegetation(scene,'woodland').map(tree).join('');
 for(const x of scene.bounds){const a=project({x,y:25}),b=project({x,y:scene.maxY});svg+=`<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#bf786a" stroke-width="1.4" stroke-dasharray="7 8" opacity=".6"/>`;}
 for(const x of scene.bounds)for(let y=35;y<scene.maxY;y+=35){const a=project({x,y});svg+=`<path d="M${a.x} ${a.y}v-${Math.max(3,11-y*.025)}" stroke="#f8f4d8" stroke-width="1.6"/>`;}
 const pin=project(scene.pin),tip=project({...scene.pin,z:4.2});svg+=`<ellipse cx="${pin.x+2}" cy="${pin.y+2}" rx="11" ry="2.4" fill="#426038" opacity=".3"/><path d="M${pin.x} ${pin.y}V${tip.y}" stroke="#284a35" stroke-width="3.6"/><path d="M${pin.x-.5} ${pin.y}V${tip.y}" stroke="#fffbed" stroke-width="1.7"/><path d="M${pin.x} ${tip.y}l23 5-23 9Z" fill="#e6c252" stroke="#fff4cd" stroke-width=".8"/><ellipse cx="${pin.x}" cy="${pin.y}" rx="3" ry="1.3" fill="#304b2f"/>`;
 return svg+overlay()+'</svg>';
}
function overlay(){const aim=project(scene.green);let out=`<g class="prototype-aim" transform="translate(${aim.x},${aim.y})"><circle r="11" fill="#fffbed18" stroke="#fffbed" stroke-width="1.6"/><path d="M-19 0h9M10 0h9M0-19v9M0 10v9" stroke="#fffbed" stroke-width="1.4"/><circle r="2.5" fill="#e5c15e"/></g>`;
 for(const h of scene.hazards.filter(h=>['water','bunker'].includes(h.kind))){const x=h.poly.reduce((n,p)=>n+p[0]/h.poly.length,0),y=h.poly.reduce((n,p)=>n+p[1]/h.poly.length,0),a=project({x,y}),left=x<scene.green.x,labelX=left?135:825,labelY=left?365:350,near=Math.min(...h.poly.map((p,i)=>{const q=h.poly[(i+1)%h.poly.length],dx=q[0]-p[0],dy=q[1]-p[1],t=Math.max(0,Math.min(1,-(p[0]*dx+p[1]*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p[0]+t*dx,p[1]+t*dy);})),label=h.kind==='water'?'Water':'Bunker';out+=`<g class="prototype-distance" data-label-side="${left?'left':'right'}" data-label-y="${labelY}" data-anchor-x="${a.x}" data-anchor-y="${a.y}"><path d="M${a.x} ${a.y}L${labelX} ${labelY}" stroke="#fff3ca" stroke-width="1" opacity=".8"/><circle cx="${a.x}" cy="${a.y}" r="3" fill="#fff3ca"/><g class="prototype-label" transform="translate(${labelX},${labelY})"><rect x="-70" y="-13" width="140" height="26" rx="5" fill="#173f32" opacity=".8"/><text x="0" y="4" text-anchor="middle" fill="#fff9e9" font-family="Arial" font-size="11">${label} ≈ ${Math.round(near)} yd</text><title>Approximate direct distance to the nearest edge; not wind-adjusted carry</title></g></g>`;}
 return out;
}
document.getElementById('proposedScene').innerHTML=proposed();
for(const el of document.querySelectorAll('[data-yardages]'))el.innerHTML=greenYardages(scene).map(v=>`<span><small>${v.kind==='front'?'FRONT':v.kind==='back'?'BACK':'FLAG'}</small><strong>${Math.round(v.distance)}</strong></span>`).join('');
document.body.classList.add('show-labels');
let mode='proposed',zoom=false;const status=document.getElementById('viewStatus');
function update(){document.getElementById('comparison').classList.toggle('both',mode==='both');document.getElementById('currentPanel').hidden=mode==='proposed';document.getElementById('proposedPanel').hidden=mode==='current';for(const [id,value]of [['proposedButton','proposed'],['currentButton','current'],['compareButton','both']])document.getElementById(id).setAttribute('aria-pressed',String(mode===value));for(const svg of document.querySelectorAll('.scene>svg'))svg.setAttribute('viewBox',zoom?'160 160 640 333.333':'0 80 960 500');for(const label of document.querySelectorAll('.prototype-distance')){const left=label.dataset.labelSide==='left',x=zoom?(left?300:660):(left?135:825),y=Number(label.dataset.labelY);label.querySelector('.prototype-label').setAttribute('transform',`translate(${x},${y})`);label.querySelector('path').setAttribute('d',`M${label.dataset.anchorX} ${label.dataset.anchorY}L${x} ${y}`);}
 document.getElementById('zoomButton').setAttribute('aria-pressed',String(zoom));document.getElementById('zoomButton').textContent=zoom?'Full view ⊖':'Close-up ⊕';status.textContent=mode==='both'?'Both illustrations use the same hole and viewpoint.':`Showing the ${mode} illustration.`;}
for(const [id,value]of [['proposedButton','proposed'],['currentButton','current'],['compareButton','both']])document.getElementById(id).addEventListener('click',()=>{mode=value;update();});
document.getElementById('zoomButton').addEventListener('click',()=>{zoom=!zoom;update();});
document.getElementById('labelsToggle').addEventListener('change',e=>document.body.classList.toggle('show-labels',e.target.checked));document.getElementById('aimToggle').addEventListener('change',e=>document.body.classList.toggle('show-aim',e.target.checked));
try{const response=await fetch('assets/prototype-current.svg');if(!response.ok)throw Error('Current illustration unavailable');const source=await response.text();const doc=new DOMParser().parseFromString(source,'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')throw Error('Invalid illustration');const svg=document.importNode(doc.documentElement,true);svg.insertAdjacentHTML('beforeend',overlay());document.getElementById('currentScene').replaceChildren(svg);document.getElementById('currentScene').setAttribute('aria-busy','false');update();}catch{document.getElementById('currentScene').textContent='The current-style comparison could not load. Refresh to try again; the proposed view is still available.';document.getElementById('currentScene').setAttribute('aria-busy','false');}

export {scene,project,update};
